    NULL,
    $j${"allowed_activities": "Tinggal dan melakukan kegiatan yang berhubungan dengan pekerjaan dalam hubungan kolaborasi dengan pemerintah, Selain itu, juga dapat melakukan kegiatan yang berhubungan dengan wisata, pembelian barang, serta mengunjungi keluarga dan teman serta kegiatan bisnis dan investasi. Anda dapat membawa keluarga untuk tinggal di Indonesia sepanjang memenuhi ketentuan peraturan perundang-undangan di bidang keimigrasian serta masuk dan keluar wilayah Indonesia selama izin masuk kembali masih berlaku. Anda juga diizinkan melakukan kegiatan lain selama memenuhi ketentuan rangkap kegiatan izin tinggal.", "code": "E33B", "dasar_hukum_verbatim": ["Undang-Undang Nomor 6 Tahun 2011 tentang Keimigrasian sebagaimana telah beberapa kali diubah terakhir dengan Undang-Undang Nomor 63 Tahun 2024 tentang Perubahan Ketiga Undang-Undang Nomor 6 Tahun 2011 tentang Keimigrasian;", "Peraturan Pemerintah Nomor 31 Tahun 2013 tentang Peraturan Pelaksanaan Undang-Undang Nomor 6 Tahun 2011 tentang Keimigrasian sebagaimana telah diubah beberapa kali terakhir dengan Peraturan Pemerintah Nomor 40 Tahun 2023 tentang Perubahan Keempat Peraturan Pemerintah Nomor 31 Tahun 2013 tentang Peraturan Pelaksanaan Undang-Undang Nomor 6 Tahun 2011 tentang Keimigrasian;", "Peraturan Pemerintah Republik Indonesia Nomor 45 Tahun 2024 tentang Jenis dan Tarif Atas Jenis Penerimaan Negara Bukan Pajak yang berlaku pada Kementerian Hukum dan Hak Asasi Manusia;", "Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal sebagaimana telah diubah dengan Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 11 Tahun 2024 tentang Perubahan Atas Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal; dan", "Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 Tahun 2025 tentang Klasifikasi Visa."], "definition_verbatim": "Visa Indeks E33B diperuntukkan bagi orang asing yang diundang oleh pemerintah karena keahliannya tanpa memerlukan penjamin, baik perorangan maupun perusahaan, dengan ketentuan menggunakan jaminan keimigrasian.", "entry": "multiple", "extendable": ["Izin Tinggal ini dapat diperpanjang dengan ketentuan keseluruhan Izin Tinggal di Wilayah Indonesia tidak lebih dari 10 (sepuluh) tahun dan dapat dialihkan menjadi izin tinggal lainnya", "Perpanjangan izin tinggal dapat dilakukan secara online oleh Orang Asing melalui akun yang telah terdaftar di evisa.imigrasi.go.id"], "http_status": 200, "itap_eligibility_as_stated_boolean": true, "itap_family_evidence": "ITAP.json", "itap_status": "LAW_MAPPED_BY_DEFINITION", "itap_verbatim": [{"section": "Jenis visa", "text": "Izin Tinggal ini dapat diperpanjang dengan ketentuan keseluruhan Izin Tinggal di Wilayah Indonesia tidak lebih dari 10 (sepuluh) tahun dan dapat dialihkan menjadi izin tinggal lainnya", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E33B"}, {"section": "Permenkumham 22/2023 Pasal 173 huruf f angka 2 (Pasal 173 as amended by Permenkumham 11/2024 angka 36; url of 22/2023, amendment at https://peraturan.go.id/id/permenkumham-no-11-tahun-2024)", "text": "Alih status Izin Tinggal Terbatas menjadi Izin Tinggal Tetap dapat diberikan kepada Orang Asing yang merupakan pemegang Izin Tinggal Terbatas yang melakukan kegiatan: ... f. rumah kedua, yang terdiri atas: 2. keahlian khusus;", "url": "https://peraturan.go.id/id/permenkumham-no-22-tahun-2023"}, {"section": "Permenkumham 22/2023 Pasal 178 and Pasal 179 ayat (1) (Pasal 173 huruf f is within the scope of Pasal 179 ayat (1))", "text": "Pasal 178: Izin Tinggal Terbatas tidak dapat dialihstatuskan menjadi Izin Tinggal Tetap, jika ketentuan pemenuhan komitmen yang dipersyaratkan saat pengajuan Izin Tinggal Terbatas pertama kali yang berasal dari Visa Tinggal Terbatas, alih status, atau peralihan belum dilaksanakan. Pasal 179 (1) Alih status Izin Tinggal Terbatas menjadi Izin Tinggal Tetap bagi Orang Asing sebagaimana dimaksud dalam Pasal 173 huruf a, huruf b, huruf c, dan huruf f diberikan dengan ketentuan Orang Asing yang bersangkutan telah berada di Wilayah Indonesia paling singkat 3 (tiga) tahun berturut-turut sejak tanggal diberikannya Izin Tinggal Terbatas.", "url": "https://peraturan.go.id/id/permenkumham-no-22-tahun-2023"}], "jenis_visa_verbatim": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu. Izin Tinggal ini dapat diperpanjang dengan ketentuan keseluruhan Izin Tinggal di Wilayah Indonesia tidak lebih dari 10 (sepuluh) tahun dan dapat dialihkan menjadi izin tinggal lainnya", "ketentuan_lain_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya"], "masa_tinggal_verbatim": "- Anda dapat tinggal di Indonesia selama 5 atau 10 tahun, sesuai dengan pilihan Anda. Izin tinggal dihitung sejak tanggal pemberian tanda masuk di Tempat Pemeriksaan Imigrasi.\n- Perpanjangan izin tinggal dapat dilakukan secara online oleh Orang Asing melalui akun yang telah terdaftar di evisa.imigrasi.go.id", "notes": ["VERIFIED_FROM_SOURCE means faithful extraction, not resolution of legal inconsistencies. Whitespace and HTML list markers are normalized; source wording, spelling, punctuation and alternatives are retained.", "stay_days retains source year-based sentences; no conversion of years into days. entry=multiple derives only from the explicit entry/exit wording. where_to_apply is null: no explicit offshore/onshore rule is stated.", "Requirements are numbered in source order. Counts include parent bullets and alternative bullets; they are not a count of simultaneously mandatory documents. Scope labels and the full Persyaratan khusus text preserve conditional context. Reference directories are retained separately and excluded from the count.", "ITAP stage (owner ruling 2026-10-18 'segui la legge'): Permenkumham 22/2023 Pasal 173 huruf f angka 2 lets a holder of this rumah-kedua ITAS convert to ITAP; mapping by card definition 'diundang oleh pemerintah karena keahliannya' / title 'Kolaborasi Keahlian Khusus' (keahlian khusus). Pasal 179 ayat (1): at least 3 consecutive years in Indonesia from the grant of the ITAS. Pasal 178: no conversion while the commitment required at the first ITAS is unfulfilled. Pasal 173 as amended by Permenkumham 11/2024 sets the senior age at 55 (the imigrasi.go.id ITAP page still says 60). The conversion is a legal-text finding; the visa page does not itself name ITAP. See ITAP.json. Status LAW_MAPPED_BY_DEFINITION: the law lists activities (Pasal 173 huruf f angka 1-4); the link from this code to the activity is an inference from its official name/definition.", "PNBP text is official reference only, never a client price.", "The reference directory headed Daftar 100 contains 109 nonempty institution entries on this page. Fifteen expertise entries and the directory wording are retained verbatim; no current ranking or list correction is substituted. Empty HTML bullets are formatting only."], "official_name_id": "E33B Visa Rumah Kedua Kolaborasi Keahlian Khusus", "page_sha256": "50e0b06114dc01e1cbe837f3034727897dcb9d2bb7a2ea28c9730b44f626ccc2", "pengajuan_intro_verbatim": "Anda harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, Anda dapat mengajukan visa setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:", "persyaratan_khusus_context_verbatim": null, "persyaratan_khusus_verbatim": "- Jaminan Keimigrasian dengan melampirkan Surat Pernyataan Komitmen akan menyampaikan bukti kerja sama dengan pemerintah atau lembaga negara;\n- Pernyataan Komitmen diatas, harus dipenuhi dan dilaporkan ke Kantor Imigrasi yang menerbitkan Izin Tinggal Terbatas dalam waktu paling lama 90 hari terhitung sejak tanggal masuk ke Indonesia dengan melampirkan bukti kerja sama dengan pemerintah atau lembaga negara;\n- dokumen lain untuk menerangkan maksud/tujuan kedatangan Orang Asing, meliputi:\n- sertifikat di bidang keahlian khusus yang dibutuhkan oleh negara; atau\n- bukti kelulusan dari salah satu dari daftar 100 (seratus) universitas terbaik dunia dalam 3 (tiga) tahun terakhir dengan nilai indeks prestasi kumulatif/grade point average paling sedikit 3,5 (tiga koma lima) atau setara.\n- Keputusan Direktur Jenderal Imigrasi Nomor IMI-0259.GR.01.01 Tahun 2023 Tentang Daftar 100 (Seratus) Universitas Terbaik Dunia Dalam 3 (Tiga) Tahun Terakhir Dan Bidang Keahlian Yang Dibutuhkan Oleh Pemerintah:\nDaftar 100 (Seratus) Universitas Terbaik Dunia, antara lain:\n-\n-\n- Massachusetts Institute of Technology (MIT)\n- University of Cambridge\n- University of Oxford\n- Harvard University\n- Stanford University\n- Imperial College London\n- ETH Zurich - Swiss Federal Institute of Technology\n- National University of Singapore\n- University College London (UCL)\n- University of California, Berkeley\n- University of Chicago\n- University of Pennsylvania\n- Cornell University\n- University of Melbourne\n- California Institute of Technology - Caltech\n- Yale University\n- Peking University\n- Princeton University\n- University of New South Wales\n- University of Sydney\n- University of Toronto\n- The University of Edinburgh\n- Columbia University\n- PSL Research University\n- Tsinghua University\n- Nanyang Technological University\n- The University of Hong Kong\n- Johns Hopkins University\n- The University of Tokyo\n- University of California, Los Angeles (UCLA)\n- McGill University\n- The University of Manchester\n- University of Michigan\n- Australian National University\n- University of British Columbia\n- Swiss Federal Institute of Technology in Lausanne\n- Technical University of Munich\n- Institut Polytechnique de Paris\n- New York University\n- King's College London\n- Seoul National University\n- Monash University\n- University of Queensland\n- Zhejiang University\n- London School of Economics and Political Science\n- Kyoto University\n- Delft University of Technology (TU Delft)\n- Northwestern University\n- The Chinese University of Hong Kong\n- Fudan University\n- Shanghai Jiao Tong University\n- Carnegie Mellon University\n- University of Amsterdam\n- Ludwig-Maximilians-University (LMU) Munich\n- University of Bristol\n- Korea Advanced Institute of Science and Technology (KAIST)\n- Duke University\n- University of Texas at Austin\n- Sorbonne University\n- Hong Kong University of Science and Technology\n- KU Leuven\n- University of California, San Diego\n- University of Washington\n- University of Illinois at Urbana Champaign\n- The Hong Kong Polytechnic University\n- University of Malaya\n- University of Warwick\n- University of Auckland\n- National Taiwan University\n- City University of Hong Kong\n- Paris-Saclay University\n- The University of Western Australia\n- Brown University\n- KTH Royal Institute of Technology\n- University of Leeds\n- University of Glasgow\n- Yonsei University\n- Durham University\n- Korea University\n- Osaka University\n- Trinity College Dublin\n- University of Southampton\n- Pennsylvania State University\n- University of Birmingham\n- Lund University\n- University of Sao Paulo\n- Heidelberg University\n- Lomonosov Moscow State University (MSU)\n- University of Adelaide\n- University of Technology Sydney\n- Tokyo Institute of Technology\n- University of Zurich\n- Boston University\n- National Autonomous University of Mexico\n- University of Buenos Aires\n- University of St Andrews\n- Georgia Institute of Technology\n- Freie Universität Berlin\n- Purdue University\n- Pohang University of Science and Technology (Postech)\n- University of Wisconsin Madison\n- University of Sheffield\n- University of Copenhagen\n- Tohoku University\n- Technical University of Denmark (DTU)\n- University of North Carolina Chapel Hill\n- University of Science and Technology of China\n- Rice University\n- Sungkyunkwan University\nBidang keahlian khusus yang dibutuhkan negara:\n-\n-\n-\n-\n-\n-\n-\n-\n- Pertanian & Perikanan;\n- Kehutanan & Penerbangan;\n- Kimia & Farmasi;\n- Mesin & Peralatan;\n- Komputer/Kecerdasan Buatan/Robotic;\n- Mesin Listrik/Elektronika;\n- Kendaraan Bermotor Energi Terbarukan;\n- Energi Terbarukan;\n- Tekstil & Busana;\n- Makanan & Minuman;\n- Kesehatan dan Pekerjaan Sosial;\n- Pendidikan, Riset, & Pengembangan;\n- Telekomunikasi;\n- Keuangan; dan\n- Pariwisata, Rekreasi Budaya, dan Olahraga.", "pnbp_verbatim_for_reference_only": ["Masa tinggal hingga 5 tahun : Rp13.000.000, terdiri atas:", "- Biaya Visa tinggal terbatas", ": Rp. 500.000,-", "- Biaya Verifikasi Visa", ": Rp. 2.000.000,-", "- Biaya Izin Tinggal Terbatas (ITAS) masa berlaku 5 Tahun", ": Rp. 7.000.000,-", "- Biaya Izin Masuk Kembali (IMK) masa berlaku 5 Tahun", ": Rp. 3.500.000,-", "Masa tinggal hingga 10 tahun : Rp19.500.000, terdiri atas:", "- Biaya Visa tinggal terbatas", ": Rp. 500.000,-", "- Biaya Verifikasi Visa", ": Rp. 2.000.000,-", "- Biaya Izin Tinggal Terbatas (ITAS) masa berlaku 10 Tahun", ": Rp. 12.000.000,-", "- Biaya Izin Masuk Kembali (IMK) masa berlaku 10 Tahun", ": Rp. 5.000.000,-", "Semua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa. Jika permohonan ditolak, maka PNBP/Biaya Imigrasi yang telah dibayarkan tidak dapat dikembalikan."], "prohibited_or_conditions_verbatim": ["Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya"], "proses_pengajuan_verbatim": "Pengajuan Visa di Direktorat Jenderal Imigrasi:\n- pemeriksaan kelengkapan persyaratan;\n- verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;\n- pembuatan profil dan verifikasi;\n- persetujuan;\n- penerbitan visa.\nWaktu proses empat hari kerja setelah pembayaran visa diterima.", "raw_path": "raw/E33B.html", "reference_lists_verbatim": ["Keputusan Direktur Jenderal Imigrasi Nomor IMI-0259.GR.01.01 Tahun 2023 Tentang Daftar 100 (Seratus) Universitas Terbaik Dunia Dalam 3 (Tiga) Tahun Terakhir Dan Bidang Keahlian Yang Dibutuhkan Oleh Pemerintah:\nDaftar 100 (Seratus) Universitas Terbaik Dunia, antara lain:\n-\n-\n- Massachusetts Institute of Technology (MIT)\n- University of Cambridge\n- University of Oxford\n- Harvard University\n- Stanford University\n- Imperial College London\n- ETH Zurich - Swiss Federal Institute of Technology\n- National University of Singapore\n- University College London (UCL)\n- University of California, Berkeley\n- University of Chicago\n- University of Pennsylvania\n- Cornell University\n- University of Melbourne\n- California Institute of Technology - Caltech\n- Yale University\n- Peking University\n- Princeton University\n- University of New South Wales\n- University of Sydney\n- University of Toronto\n- The University of Edinburgh\n- Columbia University\n- PSL Research University\n- Tsinghua University\n- Nanyang Technological University\n- The University of Hong Kong\n- Johns Hopkins University\n- The University of Tokyo\n- University of California, Los Angeles (UCLA)\n- McGill University\n- The University of Manchester\n- University of Michigan\n- Australian National University\n- University of British Columbia\n- Swiss Federal Institute of Technology in Lausanne\n- Technical University of Munich\n- Institut Polytechnique de Paris\n- New York University\n- King's College London\n- Seoul National University\n- Monash University\n- University of Queensland\n- Zhejiang University\n- London School of Economics and Political Science\n- Kyoto University\n- Delft University of Technology (TU Delft)\n- Northwestern University\n- The Chinese University of Hong Kong\n- Fudan University\n- Shanghai Jiao Tong University\n- Carnegie Mellon University\n- University of Amsterdam\n- Ludwig-Maximilians-University (LMU) Munich\n- University of Bristol\n- Korea Advanced Institute of Science and Technology (KAIST)\n- Duke University\n- University of Texas at Austin\n- Sorbonne University\n- Hong Kong University of Science and Technology\n- KU Leuven\n- University of California, San Diego\n- University of Washington\n- University of Illinois at Urbana Champaign\n- The Hong Kong Polytechnic University\n- University of Malaya\n- University of Warwick\n- University of Auckland\n- National Taiwan University\n- City University of Hong Kong\n- Paris-Saclay University\n- The University of Western Australia\n- Brown University\n- KTH Royal Institute of Technology\n- University of Leeds\n- University of Glasgow\n- Yonsei University\n- Durham University\n- Korea University\n- Osaka University\n- Trinity College Dublin\n- University of Southampton\n- Pennsylvania State University\n- University of Birmingham\n- Lund University\n- University of Sao Paulo\n- Heidelberg University\n- Lomonosov Moscow State University (MSU)\n- University of Adelaide\n- University of Technology Sydney\n- Tokyo Institute of Technology\n- University of Zurich\n- Boston University\n- National Autonomous University of Mexico\n- University of Buenos Aires\n- University of St Andrews\n- Georgia Institute of Technology\n- Freie Universität Berlin\n- Purdue University\n- Pohang University of Science and Technology (Postech)\n- University of Wisconsin Madison\n- University of Sheffield\n- University of Copenhagen\n- Tohoku University\n- Technical University of Denmark (DTU)\n- University of North Carolina Chapel Hill\n- University of Science and Technology of China\n- Rice University\n- Sungkyunkwan University\nBidang keahlian khusus yang dibutuhkan negara:\n-\n-\n-\n-\n-\n-\n-\n-\n- Pertanian & Perikanan;\n- Kehutanan & Penerbangan;\n- Kimia & Farmasi;\n- Mesin & Peralatan;\n- Komputer/Kecerdasan Buatan/Robotic;\n- Mesin Listrik/Elektronika;\n- Kendaraan Bermotor Energi Terbarukan;\n- Energi Terbarukan;\n- Tekstil & Busana;\n- Makanan & Minuman;\n- Kesehatan dan Pekerjaan Sosial;\n- Pendidikan, Riset, & Pengembangan;\n- Telekomunikasi;\n- Keuangan; dan\n- Pariwisata, Rekreasi Budaya, dan Olahraga."], "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis;"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti Jaminan Keimigrasian;"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "rekening koran pribadi dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara dalam kurun waktu 3 bulan terakhir (termasuk nama, tanggal periode, dan saldo rekening)."}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "Daftar riwayat hidup"}, {"n": 6, "section": "Pengajuan visa (berkas elektronik)", "text": "Riwayat perjalanan dan rencana perjalanan (itinerary)"}, {"n": 7, "section": "Pengajuan visa (berkas elektronik)", "text": "dokumen lain untuk menerangkan maksud/tujuan kedatangan Orang Asing"}, {"n": 8, "section": "Persyaratan Khusus", "text": "Jaminan Keimigrasian dengan melampirkan Surat Pernyataan Komitmen akan menyampaikan bukti kerja sama dengan pemerintah atau lembaga negara;"}, {"n": 9, "section": "Persyaratan Khusus", "text": "Pernyataan Komitmen diatas, harus dipenuhi dan dilaporkan ke Kantor Imigrasi yang menerbitkan Izin Tinggal Terbatas dalam waktu paling lama 90 hari terhitung sejak tanggal masuk ke Indonesia dengan melampirkan bukti kerja sama dengan pemerintah atau lembaga negara;"}, {"n": 10, "section": "Persyaratan Khusus", "text": "dokumen lain untuk menerangkan maksud/tujuan kedatangan Orang Asing, meliputi:"}, {"n": 11, "section": "Persyaratan Khusus", "text": "sertifikat di bidang keahlian khusus yang dibutuhkan oleh negara; atau"}, {"n": 12, "section": "Persyaratan Khusus", "text": "bukti kelulusan dari salah satu dari daftar 100 (seratus) universitas terbaik dunia dalam 3 (tiga) tahun terakhir dengan nilai indeks prestasi kumulatif/grade point average paling sedikit 3,5 (tiga koma lima) atau setara."}], "retrieved_at": "2026-10-17T13:27:13Z", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E33B", "sponsor_required": {"as_stated_boolean": false, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda tidak membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia selama 5 atau 10 tahun, sesuai dengan pilihan Anda."], "supplementary_stay_evidence": {"code_name_verbatim": "Visa Tinggal Terbatas untuk Orang Asing yang Diundang Pemerintah karena Keahliannya dan Akan Berkolaborasi dengan Pemerintah (E33B)", "extension_verbatim": "Orang Asing dengan Izin Tinggal pertama paling singkat 5 tahun dapat diberikan perpanjangan Izin Tinggal Terbatas untuk jangka waktu tidak melebihi jangka waktu pemberian Izin Tinggal Terbatas pertama dengan ketentuan keseluruhan Izin Tinggal Terbatas tidak lebih dari 10 tahun.", "initial_stay_verbatim": "5 tahun\n10 tahun", "page_sha256": "e429a98710f6743ee94c717f4b29a686044bc49bcd11718c7c2e8db1f041d28e", "raw_path": "raw/ITAP-central-detail.html", "retrieved_at": "2026-10-17T13:27:38Z", "scope": "ITAS duration/extension table; not an ITAP conversion entitlement.", "source_url": "https://www.imigrasi.go.id/wna/izin-tinggal-keimigrasian/izin-tinggal-tetap"}, "to_verify": ["where_to_apply", "reference_directory_label_vs_count"], "total_max_stay_verbatim": ["Izin Tinggal ini dapat diperpanjang dengan ketentuan keseluruhan Izin Tinggal di Wilayah Indonesia tidak lebih dari 10 (sepuluh) tahun dan dapat dialihkan menjadi izin tinggal lainnya"], "where_to_apply": null}$j$::jsonb,
