    NULL,
    120,
    NULL,
    $j${"allowed_activities": "Melakukan kegiatan yang berhubungan dengan investasi, bisnis, atau pembelian barang. Anda juga diizinkan bekerja selama memenuhi ketentuan rangkap izin tinggal. Selama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "code": "E33C", "dasar_hukum_verbatim": ["Undang-Undang Nomor 6 Tahun 2011 tentang Keimigrasian sebagaimana telah beberapa kali diubah terakhir dengan Undang-Undang Nomor 63 Tahun 2024 tentang Perubahan Ketiga Undang-Undang Nomor 6 Tahun 2011 tentang Keimigrasian;", "Peraturan Pemerintah Nomor 31 Tahun 2013 tentang Peraturan Pelaksanaan Undang-Undang Nomor 6 Tahun 2011 tentang Keimigrasian sebagaimana telah diubah beberapa kali terakhir dengan Peraturan Pemerintah Nomor 40 Tahun 2023 tentang Perubahan Keempat Peraturan Pemerintah Nomor 31 Tahun 2013 tentang Peraturan Pelaksanaan Undang-Undang Nomor 6 Tahun 2011 tentang Keimigrasian;", "Peraturan Pemerintah Republik Indonesia Nomor 45 Tahun 2024 tentang Jenis dan Tarif Atas Jenis Penerimaan Negara Bukan Pajak yang berlaku pada Kementerian Hukum dan Hak Asasi Manusia;", "Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal sebagaimana telah diubah dengan Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 11 Tahun 2024 tentang Perubahan Atas Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal; dan", "Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 Tahun 2025 tentang Klasifikasi Visa."], "definition_verbatim": "Visa Indeks E33C diperuntukkan bagi orang asing yang diundang oleh pemerintah karena ketokohannya dengan penjamin Pemerintah Pusat.", "entry": "multiple", "extendable": ["Izin Tinggal ini dapat diperpanjang dengan ketentuan keseluruhan Izin Tinggal di Wilayah Indonesia tidak lebih dari 10 (sepuluh) tahun dan dapat dialihkan menjadi izin tinggal lainnya", "Perpanjangan izin tinggal dapat dilakukan secara online oleh Orang Asing melalui akun yang telah terdaftar di evisa.imigrasi.go.id"], "http_status": 200, "itap_eligibility_as_stated_boolean": true, "itap_family_evidence": "ITAP.json", "itap_status": "LAW_MAPPED_BY_DEFINITION", "itap_verbatim": [{"section": "Jenis visa", "text": "Izin Tinggal ini dapat diperpanjang dengan ketentuan keseluruhan Izin Tinggal di Wilayah Indonesia tidak lebih dari 10 (sepuluh) tahun dan dapat dialihkan menjadi izin tinggal lainnya", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E33C"}, {"section": "Permenkumham 22/2023 Pasal 173 huruf f angka 3 (Pasal 173 as amended by Permenkumham 11/2024 angka 36; url of 22/2023, amendment at https://peraturan.go.id/id/permenkumham-no-11-tahun-2024)", "text": "Alih status Izin Tinggal Terbatas menjadi Izin Tinggal Tetap dapat diberikan kepada Orang Asing yang merupakan pemegang Izin Tinggal Terbatas yang melakukan kegiatan: ... f. rumah kedua, yang terdiri atas: 3. tokoh dunia; dan", "url": "https://peraturan.go.id/id/permenkumham-no-22-tahun-2023"}, {"section": "Permenkumham 22/2023 Pasal 178 and Pasal 179 ayat (1) (Pasal 173 huruf f is within the scope of Pasal 179 ayat (1))", "text": "Pasal 178: Izin Tinggal Terbatas tidak dapat dialihstatuskan menjadi Izin Tinggal Tetap, jika ketentuan pemenuhan komitmen yang dipersyaratkan saat pengajuan Izin Tinggal Terbatas pertama kali yang berasal dari Visa Tinggal Terbatas, alih status, atau peralihan belum dilaksanakan. Pasal 179 (1) Alih status Izin Tinggal Terbatas menjadi Izin Tinggal Tetap bagi Orang Asing sebagaimana dimaksud dalam Pasal 173 huruf a, huruf b, huruf c, dan huruf f diberikan dengan ketentuan Orang Asing yang bersangkutan telah berada di Wilayah Indonesia paling singkat 3 (tiga) tahun berturut-turut sejak tanggal diberikannya Izin Tinggal Terbatas.", "url": "https://peraturan.go.id/id/permenkumham-no-22-tahun-2023"}], "jenis_visa_verbatim": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu. Izin Tinggal ini dapat diperpanjang dengan ketentuan keseluruhan Izin Tinggal di Wilayah Indonesia tidak lebih dari 10 (sepuluh) tahun dan dapat dialihkan menjadi izin tinggal lainnya", "ketentuan_lain_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya"], "masa_tinggal_verbatim": "- Anda dapat tinggal di Indonesia selama 5 atau 10 tahun, sesuai dengan pilihan Anda. Izin tinggal dihitung sejak tanggal pemberian tanda masuk di Tempat Pemeriksaan Imigrasi .\n- Perpanjangan izin tinggal dapat dilakukan secara online oleh Orang Asing melalui akun yang telah terdaftar di evisa.imigrasi.go.id", "notes": ["VERIFIED_FROM_SOURCE means faithful extraction, not resolution of legal inconsistencies. Whitespace and HTML list markers are normalized; source wording, spelling, punctuation and alternatives are retained.", "stay_days retains source year-based sentences; no conversion of years into days. entry=multiple derives only from the explicit entry/exit wording. where_to_apply is null: no explicit offshore/onshore rule is stated.", "Requirements are numbered in source order. Counts include parent bullets and alternative bullets; they are not a count of simultaneously mandatory documents. Scope labels and the full Persyaratan khusus text preserve conditional context. Reference directories are retained separately and excluded from the count.", "ITAP stage (owner ruling 2026-10-18 'segui la legge'): Permenkumham 22/2023 Pasal 173 huruf f angka 3 lets a holder of this rumah-kedua ITAS convert to ITAP; mapping by card definition 'diundang oleh pemerintah karena ketokohannya' (tokoh dunia). Pasal 179 ayat (1): at least 3 consecutive years in Indonesia from the grant of the ITAS. Pasal 178: no conversion while the commitment required at the first ITAS is unfulfilled. Pasal 173 as amended by Permenkumham 11/2024 sets the senior age at 55 (the imigrasi.go.id ITAP page still says 60). The conversion is a legal-text finding; the visa page does not itself name ITAP. See ITAP.json. Status LAW_MAPPED_BY_DEFINITION: the law lists activities (Pasal 173 huruf f angka 1-4); the link from this code to the activity is an inference from its official name/definition.", "PNBP text is official reference only, never a client price.", "Sponsor is required, while Masa tinggal says extensions are made online by Orang Asing. Preserve this procedural distinction; do not infer sponsor-free initial application."], "official_name_id": "E33C Visa Rumah Kedua Tokoh Dunia Undangan Pemerintah", "page_sha256": "9b75ef7ed600898684822d9a5c0a085a079a4c84616451ad241b2322b861c328", "pengajuan_intro_verbatim": "Penjamin harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, Penjamin dapat mengajukan visa setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:", "persyaratan_khusus_context_verbatim": null, "persyaratan_khusus_verbatim": "- dokumen lain berupa undangan atau keterangan dari instansi pemerintah pusat", "pnbp_verbatim_for_reference_only": ["Masa tinggal hingga 5 tahun : Rp13.000.000, terdiri atas:", "- Biaya Visa tinggal terbatas", ": Rp. 500.000,-", "- Biaya Verifikasi Visa", ": Rp. 2.000.000,-", "- Biaya Izin Tinggal Terbatas (ITAS) masa berlaku 5 Tahun", ": Rp. 7.000.000,-", "- Biaya Izin Masuk Kembali (IMK) masa berlaku 5 Tahun", ": Rp. 3.500.000,-", "Masa tinggal hingga 10 tahun : Rp19.500.000, terdiri atas:", "- Biaya Visa tinggal terbatas", ": Rp. 500.000,-", "- Biaya Verifikasi Visa", ": Rp. 2.000.000,-", "- Biaya Izin Tinggal Terbatas (ITAS) masa berlaku 10 Tahun", ": Rp. 12.000.000,-", "- Biaya Izin Masuk Kembali (IMK) masa berlaku 10 Tahun", ": Rp. 5.000.000,-", "Semua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa. Jika permohonan ditolak, maka PNBP/Biaya Imigrasi yang telah dibayarkan tidak dapat dikembalikan."], "prohibited_or_conditions_verbatim": ["Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya"], "proses_pengajuan_verbatim": "Pengajuan Visa di Direktorat Jenderal Imigrasi:\n- pemeriksaan kelengkapan persyaratan;\n- verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;\n- pembuatan profil dan verifikasi;\n- persetujuan;\n- penerbitan visa.\nWaktu proses empat hari kerja setelah pembayaran visa diterima.", "raw_path": "raw/E33C.html", "reference_lists_verbatim": null, "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti penjaminan dari penjamin dari instansi pemerintah pusat;"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "rekening koran pribadi dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara dalam kurun waktu 3 bulan terakhir (termasuk nama, tanggal periode, dan saldo rekening)."}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "Daftar riwayat hidup"}, {"n": 6, "section": "Pengajuan visa (berkas elektronik)", "text": "Riwayat perjalanan (itinerary)"}, {"n": 7, "section": "Pengajuan visa (berkas elektronik)", "text": "dokumen lain untuk menerangkan maksud/tujuan kedatangan Orang Asing"}, {"n": 8, "section": "Persyaratan Khusus", "text": "dokumen lain berupa undangan atau keterangan dari instansi pemerintah pusat"}], "retrieved_at": "2026-10-17T13:27:13Z", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E33C", "sponsor_required": {"as_stated_boolean": true, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia selama 5 atau 10 tahun, sesuai dengan pilihan Anda."], "supplementary_stay_evidence": {"code_name_verbatim": "Visa Tinggal Terbatas untuk Tokoh Dunia (E33C)", "extension_verbatim": "Orang Asing dengan Izin Tinggal pertama paling singkat 5 tahun dapat diberikan perpanjangan Izin Tinggal Terbatas untuk jangka waktu tidak melebihi jangka waktu pemberian Izin Tinggal Terbatas pertama dengan ketentuan keseluruhan Izin Tinggal Terbatas tidak lebih dari 10 tahun.", "initial_stay_verbatim": "5 tahun\n10 tahun", "page_sha256": "e429a98710f6743ee94c717f4b29a686044bc49bcd11718c7c2e8db1f041d28e", "raw_path": "raw/ITAP-central-detail.html", "retrieved_at": "2026-10-17T13:27:38Z", "scope": "ITAS duration/extension table; not an ITAP conversion entitlement.", "source_url": "https://www.imigrasi.go.id/wna/izin-tinggal-keimigrasian/izin-tinggal-tetap"}, "to_verify": ["where_to_apply"], "total_max_stay_verbatim": ["Izin Tinggal ini dapat diperpanjang dengan ke