INSERT INTO visa_types (code, name, category, family, official_name_id, permit_class, is_sold, price_keys, entry_type, sponsor, apply_channel, initial_stay_days, extendable, max_total_days, max_total_months, itap, law_card, source_url, page_sha256, retrieved_at, card_sha256, verification_status, valid_from, valid_until, superseded_by, stay_options)
VALUES (
    'E31G',
    'E31G Visa Keluarga Orang Tua dari Anak WNI',
    'KITAS/Limited Stay',
