    NULL,
    $j${"allowed_activities": "Tinggal dan menempuh pendidikan di Indonesia.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "code": "E31H", "definition_verbatim": "Tinggal dan menempuh pendidikan di Indonesia.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "entry": "multiple", "extendable": ["Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"], "http_status": 200, "itap_assessment": {"direct_itap_context_present": false, "family_evidence": "law/E31/ITAP.json", "itas_to_itap_eligible_as_stated": null, "status": "TO_VERIFY"}, "itap_verbatim": [{"kind": "generic_conversion", "section": "Jenis visa", "text": "Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E31H"}, {"kind": "permit_reference", "section": "Persyaratan khusus", "text": "Izin Tinggal Terbatas/Izin Tinggal Tetap atau Visa Tinggal Terbatas yang masih berlaku milik anak.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E31H"}], "jenis_visa_verbatim": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "ketentuan_lain_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya", "Visa ini tidak dapat digunakan untuk tujuan bergabung dengan pemegang golden visa sebagai Family Dependant"], "not_found_evidence_verbatim": null, "notes": ["VERIFIED_FROM_SOURCE denotes faithful capture of the available page, not resolution of legal conflicts or missing fields.", "Only HTML entities, whitespace and structural list markers are normalized. Source spelling, punctuation, amounts and nested alternatives are retained.", "No offshore/onshore statement was found on the visa page; where_to_apply is null + TO_VERIFY. The evisa application channel is preserved separately.", "stay_days retains source year-based sentences; no conversion to a day count. total_max_verbatim is null when the visa page gives no cumulative limit.", "PNBP is reference only and is never a client price.", "Requirement numbers are extraction order, not official numbering. Nested alternatives remain grouped; section context and translation exceptions must be read with the items.", "A generic conversion sentence or a relative holding ITAP does not establish that this code can convert to ITAP. Code-specific conversion eligibility remains null + TO_VERIFY; see ITAP.json."], "official_name_id": "E31H Visa Keluarga Orang Tua dari Anak Pemegang ITAS/ITAP", "page_sha256": "5810897bdd9eff48bca00af907401d55b5cfc8937aa48dc8d86d66273e0b3f05", "pengajuan_intro_verbatim": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:", "persyaratan_khusus_verbatim": "- Bukti jaminan dari Penjamin atau pernyataan komitmen orang tua\n- Akta kelahiran yang telah diterjemahkan ke dalam Bahasa Indonesia oleh penerjemah tersumpah, kecuali dalam Bahasa Inggris\n- Izin Tinggal Terbatas/Izin Tinggal Tetap atau Visa Tinggal Terbatas yang masih berlaku milik anak.", "pnbp_verbatim_for_reference_only": ["Masa tinggal hingga 1 tahun : Rp. 6.000.000,-", "Komponen biaya:", "- Visa Tinggal Terbatas: Rp500.000,00", "- Biaya Verifikasi Visa Kategori I: Rp1.000.000,00", "- Izin Tinggal Terbatas paling lama 1 tahun: Rp3.000.000,00", "- Izin Masuk Kembali paling lama 1 tahun: Rp1.500.000,00", "Masa tinggal hingga 2 tahun : Rp. 8.500.000,-", "- Visa Tinggal Terbatas: Rp500.000,00", "- Biaya Verifikasi Visa Kategori I: Rp1.000.000,00", "- Izin Tinggal Terbatas paling lama 2 tahun: Rp5.000.000,00", "- Izin Masuk Kembali paling lama 2 tahun: Rp2.000.000,00"], "prohibited_or_conditions_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya", "Visa ini tidak dapat digunakan untuk tujuan bergabung dengan pemegang golden visa sebagai Family Dependant"], "raw_path": "raw/E31H.html", "requirements_context_verbatim": [{"section": "Pengajuan visa", "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:"}], "requirements_reference_verbatim": null, "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "Daftar riwayat hidup"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "Riwayat perjalanan (itinerary)"}, {"n": 6, "section": "Persyaratan khusus", "text": "Bukti jaminan dari Penjamin atau pernyataan komitmen orang tua"}, {"n": 7, "section": "Persyaratan khusus", "text": "Akta kelahiran yang telah diterjemahkan ke dalam Bahasa Indonesia oleh penerjemah tersumpah, kecuali dalam Bahasa Inggris"}, {"n": 8, "section": "Persyaratan khusus", "text": "Izin Tinggal Terbatas/Izin Tinggal Tetap atau Visa Tinggal Terbatas yang masih berlaku milik anak."}], "retrieved_at": "2026-10-17T13:27:13Z", "sections_verbatim": [{"blocks": [{"kind": "context", "text": "Tinggal dan menempuh pendidikan di Indonesia.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"}], "heading": "Dengan visa ini, anda dapat", "id": "dengan-visa-ini-anda-dapat", "items": ["Tinggal dan menempuh pendidikan di Indonesia.", "Selama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"], "text": "Tinggal dan menempuh pendidikan di Indonesia.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga"}, {"blocks": [{"kind": "context", "text": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya."}], "heading": "Jenis visa", "id": "jenis-visa", "items": ["Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.", "Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya."], "text": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya."}, {"blocks": [{"kind": "item", "text": "Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan."}, {"kind": "item", "text": "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"}], "heading": "Masa tinggal", "id": "masa-tinggal", "items": ["Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan.", "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"], "text": "- Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun dihitung sejak tanggal kedatangan.\n- Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"}, {"blocks": [{"kind": "context", "text": "Masa tinggal hingga 1 tahun : Rp. 6.000.000,-\nKomponen biaya:"}, {"kind": "item", "text": "Visa Tinggal Terbatas: Rp500.000,00"}, {"kind": "item", "text": "Biaya Verifikasi Visa Kategori I: Rp1.000.000,00"}, {"kind": "item", "text": "Izin Tinggal Terbatas paling lama 1 tahun: Rp3.000.000,00"}, {"kind": "item", "text": "Izin Masuk Kembali paling lama 1 tahun: Rp1.500.000,00"}, {"kind": "context", "text": "Masa tinggal hingga 2 tahun : Rp. 8.500.000,-"}, {"kind": "item", "text": "Visa Tinggal Terbatas: Rp500.000,00"}, {"kind": "item", "text": "Biaya Verifikasi Visa Kategori I: Rp1.000.000,00"}, {"kind": "item", "text": "Izin Tinggal Terbatas paling lama 2 tahun: Rp5.000.000,00"}, {"kind": "item", "text": "Izin Masuk Kembali paling lama 2 tahun: Rp2.000.000,00"}], "heading": "Biaya (PNBP)", "id": "biaya-pnbp", "items": ["Visa Tinggal Terbatas: Rp500.000,00", "Biaya Verifikasi Visa Kategori I: Rp1.000.000,00", "Izin Tinggal Terbatas paling lama 1 tahun: Rp3.000.000,00", "Izin Masuk Kembali paling lama 1 tahun: Rp1.500.000,00", "Visa Tinggal Terbatas: Rp500.000,00", "Biaya Verifikasi Visa Kategori I: Rp1.000.000,00", "Izin Tinggal Terbatas paling lama 2 tahun: Rp5.000.000,00", "Izin Masuk Kembali paling lama 2 tahun: Rp2.000.000,00"], "text": "Masa tinggal hingga 1 tahun : Rp. 6.000.000,-\nKomponen biaya:\n- Visa Tinggal Terbatas: Rp500.000,00\n- Biaya Verifikasi Visa Kategori I: Rp1.000.000,00\n- Izin Tinggal Terbatas paling lama 1 tahun: Rp3.000.000,00\n- Izin Masuk Kembali paling lama 1 tahun: Rp1.500.000,00\nMasa tinggal hingga 2 tahun : Rp. 8.500.000,-\n- Visa Tinggal Terbatas: Rp500.000,00\n- Biaya Verifikasi Visa Kategori I: Rp1.000.000,00\n- Izin Tinggal Terbatas paling lama 2 tahun: Rp5.000.000,00\n- Izin Masuk Kembali paling lama 2 tahun: Rp2.000.000,00"}, {"blocks": [{"kind": "context", "text": "Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."}], "heading": "Penjamin (Sponsor)", "id": "penjamin-sponsor", "items": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."], "text": "Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."}, {"blocks": [{"kind": "context", "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:"}, {"kind": "item", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,"}, {"kind": "item", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara"}, {"kind": "item", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"kind": "item", "text": "Daftar riwayat hidup"}, {"kind": "item", "text": "Riwayat perjalanan (itinerary)"}], "heading": "Pengajuan visa", "id": "pengajuan-visa", "items": ["Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,", "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara", "pasfoto berwarna terbaru (setahun terakhir). Detail", "Daftar riwayat hidup", "Riwayat perjalanan (itinerary)"], "text": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, penjamin dapat mengajukan visa bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:\n- Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,\n- bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara\n- pasfoto berwarna terbaru (setahun terakhir). Detail\n- Daftar riwayat hidup\n- Riwayat perjalanan (itinerary)"}, {"blocks": [{"kind": "item", "text": "Bukti jaminan dari Penjamin atau pernyataan komitmen orang tua"}, {"kind": "item", "text": "Akta kelahiran yang telah diterjemahkan ke dalam Bahasa Indonesia oleh penerjemah tersumpah, kecuali dalam Bahasa Inggris"}, {"kind": "item", "text": "Izin Tinggal Terbatas/Izin Tinggal Tetap atau Visa Tinggal Terbatas yang masih berlaku milik anak."}], "heading": "Persyaratan khusus", "id": "persyaratan-khusus", "items": ["Bukti jaminan dari Penjamin atau pernyataan komitmen orang tua", "Akta kelahiran yang telah diterjemahkan ke dalam Bahasa Indonesia oleh penerjemah tersumpah, kecuali dalam Bahasa Inggris", "Izin Tinggal Terbatas/Izin Tinggal Tetap atau Visa Tinggal Terbatas yang masih berlaku milik anak."], "text": "- Bukti jaminan dari Penjamin atau pernyataan komitmen orang tua\n- Akta kelahiran yang telah diterjemahkan ke dalam Bahasa Indonesia oleh penerjemah tersumpah, kecuali dalam Bahasa Inggris\n- Izin Tinggal Terbatas/Izin Tinggal Tetap atau Visa Tinggal Terbatas yang masih berlaku milik anak."}, {"blocks": [{"kind": "item", "text": "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia."}, {"kind": "item", "text": "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal."}, {"kind": "item", "text": "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi."}, {"kind": "item", "text": "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai 