VALUES (
    'D2',
    'D2 Visa Kunjungan Bisnis',
    'Visit Visa',
    'D',
    'D2 Visa Kunjungan Bisnis',
    'VISIT_MULTIPLE',
    TRUE,
    $j$[{"category": "multiple_entry_visas", "item_key": "D2 Business (1 Year)"}, {"category": "multiple_entry_visas", "item_key": "D2 Business (2 Years)"}, {"category": "multiple_entry_visas", "item_key": "D2 Business (5 Years)"}]$j$::jsonb,
    'MULTIPLE',
    'CONDITIONAL',
    NULL,
    60,
    TRUE,
    180,
    NULL,
    NULL,
    $j${"allowed_activities": "berbisnis, mengikuti rapat, serta melakukan pembelian barang. Anda juga dapat melakukan pembicaraan, pembahasan, negosiasi, dan/atau menandatangani perjanjian bisnis. Visa ini memungkinkan anda melakukan pengecekan barang di kantor, pabrik, atau tempat produksi barang. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga.", "code": "D2", "conflicts": [{"issue": "No sponsor stated for application; extension instructions refer to a sponsor.", "quotes": ["Anda tidak membutuhkan penjamin/sponsor untuk mengajukan visa ini.\nKecuali anda warga negara dari negara tertentu yang ada di dalam daftar ini", "Perpanjangan izin tinggal dapat dilakukan secara online oleh sponsor melalui akun yang telah terdaftar di evisa.imigrasi.go.id"], "status": "TO_VERIFY"}], "definition_verbatim": "berbisnis, mengikuti rapat, serta melakukan pembelian barang. Anda juga dapat melakukan pembicaraan, pembahasan, negosiasi, dan/atau menandatangani perjanjian bisnis. Visa ini memungkinkan anda melakukan pengecekan barang di kantor, pabrik, atau tempat produksi barang. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga.", "entry": "multiple", "extendable": ["Anda dapat memperpanjang izin tinggal ini beberapa kali hingga maksimal 180 hari.", "Perpanjangan izin tinggal dapat dilakukan secara online oleh sponsor melalui akun yang telah terdaftar di evisa.imigrasi.go.id", "Izin Tinggal ini dapat diperpanjang namun tidak dapat dikonversikan menjadi Izin Tinggal Terbatas."], "itap_eligibility_as_stated": null, "itap_explicit_on_visa_page": false, "itap_verbatim": [{"text": "Izin Tinggal ini dapat diperpanjang namun tidak dapat dikonversikan menjadi Izin Tinggal Terbatas.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/D2"}], "jenis_visa_verbatim": "Visa ini merupakan Visa Kunjungan untuk beberapa kali masuk ke Indonesia dengan izin tinggal maksimal 60 hari setiap kedatangan, serta dihitung sejak tanggal kedatangan. Izin Tinggal ini dapat diperpanjang namun tidak dapat dikonversikan menjadi Izin Tinggal Terbatas.", "ketentuan_lain_verbatim": ["Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa paspor sementara, paspor darurat, titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya harus melampirkan dokumen Izin Masuk Kembali ke negara tempat Visa Multipel diajukan serta tiket kembali/tiket terusan ke negara lain (kecuali bagi awak alat angkut).", "Masa berlaku visa terhitung sejak tanggal penerbitan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Orang Asing dengan izin tinggal dari Visa D2 dilarang menjual barang/jasa atau menerima imbalan/upah atau sejenisnya atas kerja/usahanya dari perorangan atau korporasi di Indonesia.", "Selain itu, pemegang izin tinggal juga dilarang melakukan supervisi secara terus menerus dari kegiatan produsen atau penjualan"], "notes": ["PNBP is official-source reference only; never a client price.", "VERIFIED_FROM_SOURCE confirms extraction, not resolution of contradictions or legal eligibility.", "Requirement numbers follow source order; nested alternatives remain verbatim. A/B counts include the application steps listed by the source."], "official_name_id": "D2 Visa Kunjungan Bisnis", "page_sha256": "0090252998e744ddecedb17494ed17eee8e3ee8237a2cf23817241ad0bdb0185", "pengajuan_intro_verbatim": "Orang asing harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa. Setelah memiliki akun, orang asing dapat mengajukan visa setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (detail format file) Orang Asing antara lain:", "persyaratan_khusus_verbatim": "surat keterangan, undangan, atau korespondensi dari instansi pemerintah atau lembaga swasta yang menjelaskan hubungan dengan Orang Asing bersangkutan; atau\nsurat keterangan dari suami/istri atau orang tua (WNI) yang menjelaskan ikatan keluarga dengan Orang Asing bersangkutan dan kegiatan Orang Asing selama berada di Indonesia (dilengkapi dengan kartu keluarga/dokumen sejenisnya).", "pnbp_verbatim_for_reference_only": ["Masa tinggal 1 tahun Rp. 4.000.000", "Komponen biaya:", "- Biaya visa 1 tahun Rp 3.000.000", "- Biaya Verifikasi I Rp 1.000.000", "Masa tinggal 2 tahun Rp 6.000.000", "Komponen biaya:", "- Biaya visa 2 tahun Rp 5.000.000", "- Biaya Verifikasi I Rp 1.000.000", "Masa tinggal 5 tahun Rp 11.000.000", "Komponen biaya:", "- Biaya visa 5 tahun Rp10.000.000", "- Biaya Verifikasi I Rp 1.000.000", "Semua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa oleh sponsor."], "prohibited_or_conditions_verbatim": ["Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa paspor sementara, paspor darurat, titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya harus melampirkan dokumen Izin Masuk Kembali ke negara tempat Visa Multipel diajukan serta tiket kembali/tiket terusan ke negara lain (kecuali bagi awak alat angkut).", "Masa berlaku visa terhitung sejak tanggal penerbitan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Orang Asing dengan izin tinggal dari Visa D2 dilarang menjual barang/jasa atau menerima imbalan/upah atau sejenisnya atas kerja/usahanya dari perorangan atau korporasi di Indonesia.", "Selain itu, pemegang izin tinggal juga dilarang melakukan supervisi secara terus menerus dari kegiatan produsen atau penjualan"], "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "dokumen perjalanan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin sebesar minimal USD2000 atau dalam mata uang lain yang setara jumlahnya,"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "curriculum vitae,"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "rencana perjalanan (travel itinerary)."}, {"n": 6, "section": "Persyaratan khusus", "text": "surat keterangan, undangan, atau korespondensi dari instansi pemerintah atau lembaga swasta yang menjelaskan hubungan dengan Orang Asing bersangkutan; atau"}, {"n": 7, "section": "Persyaratan khusus", "text": "surat keterangan dari suami/istri atau orang tua (WNI) yang menjelaskan ikatan keluarga dengan Orang Asing bersangkutan dan kegiatan Orang Asing selama berada di Indonesia (dilengkapi dengan kartu keluarga/dokumen sejenisnya)."}], "retrieved_at": "2026-10-17T13:27:31Z", "source_http_status": 200, "source_raw_path": "raw/D2.html", "source_sections_verbatim": [{"heading": "Dengan visa D2, anda dapat", "text": "berbisnis, mengikuti rapat, serta melakukan pembelian barang. Anda juga dapat melakukan pembicaraan, pembahasan, negosiasi, dan/atau menandatangani perjanjian bisnis. Visa ini memungkinkan anda melakukan pengecekan barang di kantor, pabrik, atau tempat produksi barang. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga."}, {"heading": "Jenis visa", "text": "Visa ini merupakan Visa Kunjungan untuk beberapa kali masuk ke Indonesia dengan izin tinggal maksimal 60 hari setiap kedatangan, serta dihitung sejak tanggal kedatangan. Izin Tinggal ini dapat diperpanjang namun tidak dapat dikonversikan menjadi Izin Tinggal Terbatas."}, {"heading": "Masa tinggal", "text": "Anda dapat tinggal di Indonesia maksimal 60 hari, dihitung sejak tanggal kedatangan.\nAnda dapat memperpanjang izin tinggal ini beberapa kali hingga maksimal 180 hari.\nPerpanjangan izin tinggal dapat dilakukan secara online oleh sponsor melalui akun yang telah terdaftar di evisa.imigrasi.go.id"}, {"heading": "Biaya (PNBP)", "text": "Masa tinggal 1 tahun Rp. 4.000.000\nKomponen biaya:\nBiaya visa 1 tahun Rp 3.000.000\nBiaya Verifikasi I Rp 1.000.000\nMasa tinggal 2 tahun Rp 6.000.000\nKomponen biaya:\nBiaya visa 2 tahun Rp 5.000.000\nBiaya Verifikasi I Rp 1.000.000\nMasa tinggal 5 tahun Rp 11.000.000\nKomponen biaya:\nBiaya visa 5 tahun Rp10.000.000\nBiaya Verifikasi I Rp 1.000.000\nSemua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa oleh sponsor."}, {"heading": "Penjamin (Sponsor)", "text": "Anda tidak membutuhkan penjamin/sponsor untuk mengajukan visa ini.\nKecuali anda warga negara dari negara tertentu yang ada di dalam daftar ini"}, {"heading": "Pengajuan visa", "text": "Orang asing harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa. Setelah memiliki akun, orang asing dapat mengajukan visa setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (detail format file) Orang Asing antara lain:\ndokumen perjalanan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,\nbukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin sebesar minimal USD2000 atau dalam mata uang lain yang setara jumlahnya,\npasfoto berwarna terbaru (setahun terakhir). Detail\ncurriculum vitae,\nrencana perjalanan (travel itinerary)."}, {"heading": "Persyaratan khusus", "text": "surat keterangan, undangan, atau korespondensi dari instansi pemerintah atau lembaga swasta yang menjelaskan hubungan dengan Orang Asing bersangkutan; atau\nsurat keterangan dari suami/istri atau orang tua (WNI) yang menjelaskan ikatan keluarga dengan Orang Asing bersangkutan dan kegiatan Orang Asing selama berada di Indonesia (dilengkapi dengan kartu keluarga/dokumen sejenisnya)."}, {"heading": "Ketentuan lain", "text": "Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa paspor sementara, paspor darurat, titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya harus melampirkan dokumen Izin Masuk Kembali ke negara tempat Visa Multipel diajukan serta tiket kembali/tiket terusan ke negara lain (kecuali bagi awak alat angkut).\nMasa berlaku visa terhitung sejak tanggal penerbitan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.\nOrang Asing dengan izin tinggal dari Visa D2 dilarang menjual barang/jasa atau menerima imbalan/upah atau sejenisnya atas kerja/usahanya dari perorangan atau korporasi di Indonesia.\nSelain itu, pemegang izin tinggal juga dilarang melakukan supervisi secara terus menerus dari kegiatan produsen atau penjualan"}, {"heading": "Proses pengajuan dan pemberian visa", "text": "Pengajuan Visa di Direktorat Jenderal Imigrasi:\npemeriksaan kelengkapan persyaratan;\nverifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;\npembuatan profil dan verifikasi;\npersetujuan;\npenerbitan visa.\nWaktu Proses lima hari kerja setelah pembayaran visa diterima."}, {"heading": "Dasar hukum", "text": "Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI\nPeraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal\nPeraturan Menteri Hukum dan HAM RI Nomor 22 tahun 2023 tentang Visa dan Izin Tinggal\nKeputusan Menteri Imigrasi dan Pemasyarakatan Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa\nPeraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI\nPeraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"}], "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/D2", "sponsor_required": {"as_stated_boolean": false, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda tidak membutuhkan penjamin/sponsor untuk mengajukan visa ini.", "Kecuali anda warga negara dari negara tertentu yang ada di dalam daftar ini"]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia maksimal 60 hari, dihitung sejak tanggal kedatangan."], "to_verify": ["where_to_apply: null + TO_VERIFY; no explicit offshore/onshore application rule on the visa page.", "conflicts: No sponsor stated for application; extension instructions refer to a sponsor.", "Sponsor nationality exception: linked country list is a separate source; not inferred here."], "total_max_verbatim": ["Anda dapat memperpanjang izin tinggal ini beberapa kali hingga maksimal 180 hari."], "where_to_apply": null}$j$::jsonb,
