    60,
    NULL,
    NULL,
    $j${"allowed_activities": "menjalankan tugas pemerintahan, mengunjungi suatu tempat atau melakukan kegiatan dalam rangka tugas resmi pemerintahan. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga.", "application_routes_verbatim": [{"heading": "Permohonan dan Pembayaran Pra Kedatangan", "text": "Orang asing dari negara subjek visa kunjungan saat kedatangan harus:\nmengajukan permohonan melalui evisa.imigrasi.go.id\nmengisi formulir dan mengunggah berkas secara elektronik, antara lain:\na. halaman biodata paspor yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)\nb. pasfoto berwarna terbaru (setahun terakhir). Detail\nc. tiket kembali atau tiket terusan ke negara lain, kecuali bagi awak alat angkut yang akan singgah untuk bergabung dengan kapalnya dan melanjutkan perjalanan ke negara lain\nmembayar menggunakan metode pembayaran digital melalui kartu debit/kredit\nmengecek dalam akun evisa dan email, karena visa kunjungan saat kedatangan elektronik akan dikirimkan oleh sistem dalam waktu 1x24 jam."}, {"heading": "Permohonan Pra Kedatangan dan Pembayaran Saat Kedatangan", "text": "Orang asing dari negara subjek visa kunjungan saat kedatangan harus:\nmengajukan permohonan melalui evisa.imigrasi.go.id\nmengisi formulir dan mengunggah berkas secara elektronik, antara lain:\na. halaman biodata paspor yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)\nb. pasfoto berwarna terbaru (setahun terakhir). Detail\nc. tiket kembali atau tiket terusan ke negara lain, kecuali bagi awak alat angkut yang akan singgah untuk bergabung dengan kapalnya dan melanjutkan perjalanan ke negara lain\nmembayar menggunakan metode pembayaran digital melalui kartu debit/kredit\nmengambil visa kunjungan saat kedatangan elektronik di konter visa."}, {"heading": "Permohonan dan Pembayaran Saat Kedatangan", "text": "Orang asing dari negara subjek visa kunjungan saat kedatangan akan:\nmelakukan pembayaran Visa Kunjungan Saat Kedatangan di konter Bank yang ditunjuk pada area imigrasi bandar udara/pelabuhan dengan menunjukkan paspor yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis kepada petugas\nmemperoleh Vaucer Visa, kertas sekuriti sebagai tanda bukti pembayaran Visa kunjungan saat kedatangan\nmenunjukkan Vaucer Visa kepada petugas imigrasi pada konter Visa Kunjungan Saat Kedatangan\nmemperoleh stiker Visa Kunjungan Saat Kedatangan yang ditempelkan pada paspor serta tanda masuk elektronik."}], "code": "B4", "conflicts": [], "definition_verbatim": "menjalankan tugas pemerintahan, mengunjungi suatu tempat atau melakukan kegiatan dalam rangka tugas resmi pemerintahan. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga.", "entry": "single", "extendable": ["Anda dapat memperpanjang izin tinggal ini satu kali hingga (keseluruhan masa tinggal) maksimal 60 hari.", "Bagi pemegang e-VoA (visa kunjungan saat kedatangan elektronik), perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id.", "Bagi pemegang VoA nonelektronik, perpanjangan izin tinggal dapat dilakukan di kantor imigrasi terdekat dari domisili anda.", "Izin Tinggal ini dapat diperpanjang satu kali dan dapat dialihkan menjadi izin tinggal lain melalui mekanisme bridging visa."], "itap_eligibility_as_stated": null, "itap_explicit_on_visa_page": false, "itap_verbatim": [{"text": "Izin Tinggal ini dapat diperpanjang satu kali dan dapat dialihkan menjadi izin tinggal lain melalui mekanisme bridging visa.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/B4"}], "jenis_visa_verbatim": "Visa ini merupakan Visa Kunjungan Saat Kedatangan (Visa on Arrival) bagi negara subjek visa kunjungan saat kedatangan untuk satu kali masuk ke Indonesia dengan izin tinggal pertama kali maksimal 30 hari, dihitung sejak tanggal kedatangan. Izin Tinggal ini dapat diperpanjang satu kali dan dapat dialihkan menjadi izin tinggal lain melalui mekanisme bridging visa.", "ketentuan_lain_verbatim": ["Orang Asing pemegang dokumen perjalanan bukan paspor kebangsaan berupa paspor sementara (temporary passport) dan paspor darurat (emergency passport) diizinkan mengajukan visa kunjungan saat kedatangan", "Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya tidak diizinkan mengajukan visa kunjungan saat kedatangan.", "Masa berlaku visa kunjungan saat kedatangan elektronik (e-voa) adalah 90 hari sejak diterbitkan. Jika tidak digunakan dalam jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Visa kunjungan saat kedatangan nonelektronik langsung digunakan setelah terbit", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Orang Asing dengan izin tinggal dari visa ini dilarang menjual barang atau jasa atau menerima imbalan, upah, atau sejenisnya atas kerja/usahanya dari perorangan atau korporasi di Indonesia."], "notes": ["PNBP is official-source reference only; never a client price.", "VERIFIED_FROM_SOURCE confirms extraction, not resolution of contradictions or legal eligibility.", "Requirement numbers follow source order; nested alternatives remain verbatim. A/B counts include the application steps listed by the source."], "official_name_id": "B4 Visa Kunjungan Penugasan Pemerintahan", "page_sha256": "de02bb3433bd8b8042f762a416cf2c368bb74a4a26bc5929f925e0e066ae2052", "pengajuan_intro_verbatim": null, "pnbp_verbatim_for_reference_only": ["- Biaya visa B4 Rp 500.000 (untuk 30 hari)", "- Biaya Verifikasi I/II Rp 0", "- Pembayaran Visa Kunjungan Saat Kedatangan elektronik (e-VoA): pembayaran digital dengan kartu debit/kredit", "- Pembayaran Visa Kunjungan Saat Kedatangan nonelektronik: Konter bank yang ditunjuk pada area pemeriksaan imigrasi"], "prohibited_or_conditions_verbatim": ["Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya tidak diizinkan mengajukan visa kunjungan saat kedatangan.", "Masa berlaku visa kunjungan saat kedatangan elektronik (e-voa) adalah 90 hari sejak diterbitkan. Jika tidak digunakan dalam jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Orang Asing dengan izin tinggal dari visa ini dilarang menjual barang atau jasa atau menerima imbalan, upah, atau sejenisnya atas kerja/usahanya dari perorangan atau korporasi di Indonesia."], "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa / Permohonan dan Pembayaran Pra Kedatangan", "text": "mengajukan permohonan melalui evisa.imigrasi.go.id"}, {"n": 2, "section": "Pengajuan visa / Permohonan dan Pembayaran Pra Kedatangan", "text": "mengisi formulir dan mengunggah berkas secara elektronik, antara lain:\na. halaman biodata paspor yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)\nb. pasfoto berwarna terbaru (setahun terakhir). Detail\nc. tiket kembali atau tiket terusan ke negara lain, kecuali bagi awak alat angkut yang akan singgah untuk bergabung dengan kapalnya dan melanjutkan perjalanan ke negara lain"}, {"n": 3, "section": "Pengajuan visa / Permohonan dan Pembayaran Pra Kedatangan", "text": "membayar menggunakan metode pembayaran digital melalui kartu debit/kredit"}, {"n": 4, "section": "Pengajuan visa / Permohonan dan Pembayaran Pra Kedatangan", "text": "mengecek dalam akun evisa dan email, karena visa kunjungan saat kedatangan elektronik akan dikirimkan oleh sistem dalam waktu 1x24 jam."}, {"n": 5, "section": "Pengajuan visa / Permohonan Pra Kedatangan dan Pembayaran Saat Kedatangan", "text": "mengajukan permohonan melalui evisa.imigrasi.go.id"}, {"n": 6, "section": "Pengajuan visa / Permohonan Pra Kedatangan dan Pembayaran Saat Kedatangan", "text": "mengisi formulir dan mengunggah berkas secara elektronik, antara lain:\na. halaman biodata paspor yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)\nb. pasfoto berwarna terbaru (setahun terakhir). Detail\nc. tiket kembali atau tiket terusan ke negara lain, kecuali bagi awak alat angkut yang akan singgah untuk bergabung dengan kapalnya dan melanjutkan perjalanan ke negara lain"}, {"n": 7, "section": "Pengajuan visa / Permohonan Pra Kedatangan dan Pembayaran Saat Kedatangan", "text": "membayar menggunakan metode pembayaran digital melalui kartu debit/kredit"}, {"n": 8, "section": "Pengajuan visa / Permohonan Pra Kedatangan dan Pembayaran Saat Kedatangan", "text": "mengambil visa kunjungan saat kedatangan elektronik di konter visa."}, {"n": 9, "section": "Pengajuan visa / Permohonan dan Pembayaran Saat Kedatangan", "text": "melakukan pembayaran Visa Kunjungan Saat Kedatangan di konter Bank yang ditunjuk pada area imigrasi bandar udara/pelabuhan dengan menunjukkan paspor yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis kepada petugas"}, {"n": 10, "section": "Pengajuan visa / Permohonan dan Pembayaran Saat Kedatangan", "text": "memperoleh Vaucer Visa, kertas sekuriti sebagai tanda bukti pembayaran Visa kunjungan saat kedatangan"}, {"n": 11, "section": "Pengajuan visa / Permohonan dan Pembayaran Saat Kedatangan", "text": "menunjukkan Vaucer Visa kepada petugas imigrasi pada konter Visa Kunjungan Saat Kedatangan"}, {"n": 12, "section": "Pengajuan visa / Permohonan dan Pembayaran Saat Kedatangan", "text": "memperoleh stiker Visa Kunjungan Saat Kedatangan yang ditempelkan pada paspor serta tanda masuk elektronik."}], "retrieved_at": "2026-10-17T13:27:30Z", "source_http_status": 200, "source_raw_path": "raw/B4.html", "source_sections_verbatim": [{"heading": "Dengan visa B4, anda dapat", "text": "menjalankan tugas pemerintahan, mengunjungi suatu tempat atau melakukan kegiatan dalam rangka tugas resmi pemerintahan. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga."}, {"heading": "Jenis visa", "text": "Visa ini merupakan Visa Kunjungan Saat Kedatangan (Visa on Arrival) bagi negara subjek visa kunjungan saat kedatangan untuk satu kali masuk ke Indonesia dengan izin tinggal pertama kali maksimal 30 hari, dihitung sejak tanggal kedatangan. Izin Tinggal ini dapat diperpanjang satu kali dan dapat dialihkan menjadi izin tinggal lain melalui mekanisme bridging visa."}, {"heading": "Masa tinggal", "text": "Anda dapat tinggal di Indonesia maksimal 30 hari, dihitung sejak tanggal kedatangan.\nAnda dapat memperpanjang izin tinggal ini satu kali hingga (keseluruhan masa tinggal) maksimal 60 hari.\nBagi pemegang e-VoA (visa kunjungan saat kedatangan elektronik), perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id.\nBagi pemegang VoA nonelektronik, perpanjangan izin tinggal dapat dilakukan di kantor imigrasi terdekat dari domisili anda."}, {"heading": "Biaya (PNBP)", "text": "Biaya visa B4 Rp 500.000 (untuk 30 hari)\nBiaya Verifikasi I/II Rp 0\nPembayaran Visa Kunjungan Saat Kedatangan elektronik (e-VoA): pembayaran digital dengan kartu debit/kredit\nPembayaran Visa Kunjungan Saat Kedatangan nonelektronik: Konter bank yang ditunjuk pada area pemeriksaan imigrasi"}, {"heading": "Penjamin (Sponsor)", "text": "Anda tidak membutuhkan penjamin/sponsor untuk mengajukan visa ini."}, {"heading": "Pengajuan visa", "text": "Permohonan dan Pembayaran Pra Kedatangan\nOrang asing dari negara subjek visa kunjungan saat kedatangan harus:\nmengajukan permohonan melalui evisa.imigrasi.go.id\nmengisi formulir dan mengunggah berkas secara elektronik, antara lain:\na. halaman biodata paspor yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)\nb. pasfoto berwarna terbaru (setahun terakhir). Detail\nc. tiket kembali atau tiket terusan ke negara lain, kecuali bagi awak alat angkut yang akan singgah untuk bergabung dengan kapalnya dan melanjutkan perjalanan ke negara lain\nmembayar menggunakan metode pembayaran digital melalui kartu debit/kredit\nmengecek dalam akun evisa dan email, karena visa kunjungan saat kedatangan elektronik akan dikirimkan oleh sistem dalam waktu 1x24 jam.\nPermohonan Pra Kedatangan dan Pembayaran Saat Kedatangan\nOrang asing dari negara subjek visa kunjungan saat kedatangan harus:\nmengajukan permohonan melalui evisa.imigrasi.go.id\nmengisi formulir dan mengunggah berkas secara elektronik, antara lain:\na. halaman biodata paspor yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)\nb. pasfoto berwarna terbaru (setahun terakhir). Detail\nc. tiket kembali atau tiket terusan ke negara lain, kecuali bagi awak alat angkut yang akan singgah untuk bergabung dengan kapalnya dan melanjutkan perjalanan ke negara lain\nmembayar menggunakan metode pembayaran digital melalui kartu debit/kredit\nmengambil visa kunjungan saat kedatangan elektronik di konter visa.\nPermohonan dan Pembayaran Saat Kedatangan\nOrang asing dari negara subjek visa kunjungan saat kedatangan akan:\nmelakukan pembayaran Visa Kunjungan Saat Kedatangan di konter Bank yang ditunjuk pada area imigrasi bandar udara/pelabuhan dengan menunjukkan paspor yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis kepada petugas\nmemperoleh Vaucer Visa, kertas sekuriti sebagai tanda bukti pembayaran Visa kunjungan saat kedatangan\nmenunjukkan Vaucer Visa kepada petugas imigrasi pada konter Visa Kunjungan Saat Kedatangan\nmemperoleh stiker Visa Kunjungan Saat Kedatangan yang ditempelkan pada paspor serta tanda masuk elektronik."}, {"heading": "Ketentuan lain", "text": "Orang Asing pemegang dokumen perjalanan bukan paspor kebangsaan berupa paspor sementara (temporary passport) dan paspor darurat (emergency passport) diizinkan mengajukan visa kunjungan saat kedatangan\nOrang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya tidak diizinkan mengajukan visa kunjungan saat kedatangan.\nMasa berlaku visa kunjungan saat kedatangan elektronik (e-voa) adalah 90 hari sejak diterbitkan. Jika tidak digunakan dalam jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.\nVisa kunjungan saat kedatangan nonelektronik langsung digunakan setelah terbit\nHarap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.\nOrang Asing dengan izin tinggal dari visa ini dilarang menjual barang atau jasa atau menerima imbalan, upah, atau sejenisnya atas kerja/usahanya dari perorangan atau korporasi di Indonesia."}, {"heading": "Dasar hukum", "text": "Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI\nPeraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal\nPeraturan Menteri Hukum dan HAM RI Nomor 22 tahun 2023 tentang Visa dan Izin Tinggal\nKeputusan Menteri Imigrasi dan Pemasyarakatan Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa\nPeraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI\nPeraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"}], "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/B4", "sponsor_required": {"as_stated_boolean": false, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda tidak membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia maksimal 30 hari, dihitung sejak tanggal kedatangan."], "to_verify": [], "total_max_verbatim": ["Anda dapat memperpanjang izin tinggal ini satu kali hingga (keseluruhan masa tinggal) maksimal 60 hari."], "where_to_apply": "Permohonan dan Pembayaran Pra Kedatangan\nPermohonan Pra Kedatangan dan Pembayaran Saat Kedatangan\nPermohonan dan Pembayaran Saat Kedatangan"}$j$::jsonb,
    'https://www.imigrasi.go.id/wna/daftar-visa-indonesia/B4',
