UPDATE visa_types SET
    law_card = $j${"allowed_activities": "Tinggal di Indonesia serta melaksanakan kegiatan yang berhubungan dengan bisnis, rapat, atau perbelanjaan termasuk pengecekan barang di kantor, pabrik, atau tempat produksi barang.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "code": "E33F", "dasar_hukum_verbatim": ["Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM", "Peraturan Menteri Hukum dan HAM RI Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal", "Peraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal", "Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa", "Peraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI", "Peraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"], "definition_verbatim": "Tinggal di Indonesia serta melaksanakan kegiatan yang berhubungan dengan bisnis, rapat, atau perbelanjaan termasuk pengecekan barang di kantor, pabrik, atau tempat produksi barang.\nSelama Izin Masuk Kembali masih berlaku, Anda diizinkan untuk masuk dan keluar wilayah Indonesia. Selain itu, Anda juga dapat melakukan aktivitas yang berhubungan dengan wisata, mengunjungi teman atau keluarga", "entry": "multiple", "extendable": ["Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id"], "http_status": 200, "itap_eligibility_as_stated_boolean": true, "itap_family_evidence": "ITAP.json", "itap_status": "LAW_MAPPED_BY_TITLE", "itap_verbatim": [{"section": "Jenis visa", "text": "Izin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E33F"}, {"section": "Permenkumham 22/2023 Pasal 173 huruf f angka 4 (Pasal 173 as amended by Permenkumham 11/2024 angka 36; url of 22/2023, amendment at https://peraturan.go.id/id/permenkumham-no-11-tahun-2024)", "text": "Alih status Izin Tinggal Terbatas menjadi Izin Tinggal Tetap dapat diberikan kepada Orang Asing yang merupakan pemegang Izin Tinggal Terbatas yang melakukan kegiatan: ... f. rumah kedua, yang terdiri atas: 4. lanjut usia berusia 55 (lima puluh lima) tahun atau lebih.", "url": "https://peraturan.go.id/id/permenkumham-no-22-tahun-2023"}, {"section": "Permenkumham 22/2023 Pasal 178 and Pasal 179 ayat (1) (Pasal 173 huruf f is within the scope of Pasal 179 ayat (1))", "text": "Pasal 178: Izin Tinggal Terbatas tidak dapat dialihstatuskan menjadi Izin Tinggal Tetap, jika ketentuan pemenuhan komitmen yang dipersyaratkan saat pengajuan Izin Tinggal Terbatas pertama kali yang berasal dari Visa Tinggal Terbatas, alih status, atau peralihan belum dilaksanakan. Pasal 179 (1) Alih status Izin Tinggal Terbatas menjadi Izin Tinggal Tetap bagi Orang Asing sebagaimana dimaksud dalam Pasal 173 huruf a, huruf b, huruf c, dan huruf f diberikan dengan ketentuan Orang Asing yang bersangkutan telah berada di Wilayah Indonesia paling singkat 3 (tiga) tahun berturut-turut sejak tanggal diberikannya Izin Tinggal Terbatas.", "url": "https://peraturan.go.id/id/permenkumham-no-22-tahun-2023"}], "jenis_visa_verbatim": "Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu.\nIzin Tinggal dari jenis visa ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "ketentuan_lain_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya"], "masa_tinggal_verbatim": "Anda dapat tinggal di Indonesia selama 1 tahun. Perpanjangan izin tinggal dapat dilakukan secara online melalui evisa.imigrasi.go.id", "notes": ["VERIFIED_FROM_SOURCE means faithful extraction, not resolution of legal inconsistencies. Whitespace and HTML list markers are normalized; source wording, spelling, punctuation and alternatives are retained.", "stay_days retains source year-based sentences; no conversion of years into days. entry=multiple derives only from the explicit entry/exit wording. where_to_apply is null: no explicit offshore/onshore rule is stated.", "Requirements are numbered in source order. Counts include parent bullets and alternative bullets; they are not a count of simultaneously mandatory documents. Scope labels and the full Persyaratan khusus text preserve conditional context. Reference directories are retained separately and excluded from the count.", "ITAP stage (owner ruling 2026-10-18 'segui la legge'): Permenkumham 22/2023 Pasal 173 huruf f angka 4 lets a holder of this rumah-kedua ITAS convert to ITAP; mapping by title 'Lansia Untuk 1 Tahun' (lanjut usia; the visa page itself states no minimum age, which stays TO_VERIFY). Pasal 179 ayat (1): at least 3 consecutive years in Indonesia from the grant of the ITAS. Pasal 178: no conversion while the commitment required at the first ITAS is unfulfilled. Pasal 173 as amended by Permenkumham 11/2024 sets the senior age at 55 (the imigrasi.go.id ITAP page still says 60). The conversion is a legal-text finding; the visa page does not itself name ITAP. See ITAP.json. Status LAW_MAPPED_BY_TITLE: the law lists activities (Pasal 173 huruf f angka 1-4); the link from this code to the activity is an inference from its official title only.", "55-vs-60 conflict inside the law: Permenkumham 11/2024 amends Pasal 173 huruf f angka 4 (and Pasal 33 ayat (2) huruf j angka 4) to 55 years, but its own restated Pasal 105 ayat (10) huruf d still reads 'Orang Asing lanjut usia berusia 60 (enam puluh) tahun atau lebih', and the imigrasi.go.id ITAP page says 60. The ITAP boolean follows Pasal 173 (55); the age threshold stays TO_VERIFY. Also, 11/2024 Pasal 33 ayat (2) huruf j angka 4 writes '55 (lima puluh)' (numeral and words disagree), while Pasal 173 huruf f angka 4 reads '55 (lima puluh lima)'.", "PNBP text is official reference only, never a client price.", "The page title identifies Lansia, but its substantive text states no minimum age and no sponsor organization type. Neither is inferred from E33E or generic ITAP information."], "official_name_id": "E33F Visa Rumah Kedua Lansia Untuk 1 Tahun", "page_sha256": "8c15016f2ce1adb8df695bb4e3b9098d7785e15fef3686c2c0bafea4128dd84e", "pengajuan_intro_verbatim": "Penjamin harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori.\nSetelah memiliki akun, Penjamin dapat mengajukan visa setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (file PDF atau JPEG) Orang Asing antara lain:", "persyaratan_khusus_context_verbatim": null, "persyaratan_khusus_verbatim": "- Bukti penghasilan atau tunjangan dengan nilai sekurang-kurangnya US$3.000 (tiga ribu dolar Amerika Serikat) per bulan.", "pnbp_verbatim_for_reference_only": ["- Masa tinggal 1 tahun: Rp.7.000.000,-", "Visa Tinggal Terbatas: Rp500.000,00", "Biaya Verifikasi Visa Kategori II: Rp2.000.000,00", "Izin Tinggal Terbatas paling lama 1 tahun: Rp3.000.000,00", "Izin Masuk Kembali paling lama 1 tahun: Rp1.500.000,00"], "prohibited_or_conditions_verbatim": ["Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, terkecuali diperlukan dalam pekerjaannya"], "proses_pengajuan_verbatim": "Pengajuan Visa di Direktorat Jenderal Imigrasi:\n- pemeriksaan kelengkapan persyaratan;\n- verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;\n- pembuatan profil dan verifikasi;\n- persetujuan;\n- penerbitan visa.\nWaktu proses lima hari kerja setelah pembayaran visa diterima.", "raw_path": "raw/E33F.html", "reference_lists_verbatim": null, "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "Surat penjaminan dari penjamin"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin dengan jumlah minimal USD $2000 (dua ribu Dolar Amerika Serikat) atau jumlah yang setara"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "Daftar riwayat hidup"}, {"n": 6, "section": "Pengajuan visa (berkas elektronik)", "text": "Riwayat perjalanan (itinerary)"}, {"n": 7, "section": "Persyaratan Khusus", "text": "Bukti penghasilan atau tunjangan dengan nilai sekurang-kurangnya US$3.000 (tiga ribu dolar Amerika Serikat) per bulan."}], "retrieved_at": "2026-10-17T13:27:13Z", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E33F", "sponsor_required": {"as_stated_boolean": true, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia selama 1 tahun."], "supplementary_stay_evidence": {"code_name_verbatim": "Visa Tinggal Terbatas untuk Lanjut Usia (E33F)", "extension_verbatim": "Dapat diberikan perpanjangan ITAS untuk jangka waktu tidak melebihi jangka waktu pemberian ITAS pertama dengan ketentuan keseluruhan ITAS tidak lebih dari 6 tahun.", "initial_stay_verbatim": "1 tahun", "page_sha256": "e429a98710f6743ee94c717f4b29a686044bc49bcd11718c7c2e8db1f041d28e", "raw_path": "raw/ITAP-central-detail.html", "retrieved_at": "2026-10-17T13:27:38Z", "scope": "ITAS duration/extension table; not an ITAP conversion entitlement.", "source_url": "https://www.imigrasi.go.id/wna/izin-tinggal-keimigrasian/izin-tinggal-tetap"}, "to_verify": ["where_to_apply", "total_max_stay_verbatim", "minimum_age_not_stated", "sponsor_type_not_stated", "senior_age_threshold_55_vs_60"], "total_max_stay_verbatim": null, "where_to_apply": null}$j$::jsonb,
